  $stream = $client.GetStream()
  function Send-Arr($arr){
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("*"+$arr.Count+"`r`n")
    foreach($a in $arr){ [void]$sb.Append("$"+$a.Length+"`r`n"+$a+"`r`n") }
